(D/'results.json').write_text(json.dumps(dict(headline=headline,summary_html=summary,native=native,mount_sensitivity=h7,mesh_h6=h6,mesh_h5=h5,orthotropic_reference=ortho,patch_2x=patch2,motion=motion,installation=install,installation_candidates=candidates,hoop=hoop,project=project),indent=2)+'\n')
(B/'REPORT.md').write_text('# HX04 extended engineering audit\n\n'+headline+'\n\nThe authored full report is [report.html](../../../docs/gallery/key-fan/studies/report.html); the interactive study uses exact source and field hashes in scene.json.\n\n'+ '\n\n'.join('## '+re.split(r'</h2>',q,1)[0].split('<h2>')[1] for q in texts)+'\n') if False else None
(B/'report-build.json').write_text(json.dumps(dict(source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),report_sha256=hashlib.sha256((D/'report.html').read_bytes()).hexdigest(),results_sha256=hashlib.sha256((D/'results.json').read_bytes()).hexdigest(),scope='Authored audit of immutable published v2 geometry; no physical qualification'),indent=2)+'\n')
print('Built complete numerical report, tables and five scientific plots')
